        if tokens[0] == 'null':
            tokens.pop(0)
            return None
        elif tokens[0] == 'true':
            tokens.pop(0)
            return True
        elif tokens[0] == 'false':
            tokens.pop(0)
            return False
        elif tokens[0] == '{':
            tokens.pop(0)
            result = {}
            while tokens[0] != '}':
                key = parse_value(tokens)
                if tokens[0] != ':':
                    raise ValueError("Expected ':' after key")
                tokens.pop(0)
                value = parse_value(tokens)
                result[key] = value
                if tokens[0] == ',':
                    tokens.pop(0)
            tokens.pop(0)
            return result
        elif tokens[0] == '[':
            tokens.pop(0)
            result = []
            while tokens[0] != ']':
                value = parse_value(tokens)
                result.append(value)
                if tokens[0] == ',':
                    tokens.pop(0)
            tokens.pop(0)
            return result
        elif tokens[0].isdigit() or (tokens[0] == '-' and tokens[1].isdigit()):
            num = ''
            while tokens[0].isdigit() or tokens[0] == '.':
                num += tokens.pop(0)
            if '.' in num:
                return float(num)
            else:
                return int(num)
        elif tokens[0] == '"':
            tokens.pop(0)
            result = ''
            while tokens[0] != '"':
                if tokens[0] == '\\':
                    tokens.pop(0)
                    if tokens[0] == '"':
                        result += '"'
                    elif tokens[0] == '\\':
                        result += '\\'
                    elif tokens[0] == '/':
                        result += '/'
                    elif tokens[0] == 'b':
                        result += '\b'
                    elif tokens[0] == 'f':
                        result += '\f'
                    elif tokens[0] == 'n':
                        result += '\n'
                    elif tokens[0] == 'r':
                        result += '\r'
                    elif tokens[0] == 't':
                        result += '\t'
                    else:
                        raise ValueError("Invalid escape sequence")
                else:
                    result += tokens.pop(0)
            tokens.pop(0)
            return result
        else:
            raise ValueError("Invalid JSON syntax")

    def tokenize(json_str):
        tokens = []
        i = 0
        while i < len(json_str):
            if json_str[i] == '{' or json_str[i] == '}' or json_str[i] == '[' or json_str[i] == ']':
                tokens.append(json_str[i])
                i += 1
            elif json_str[i] == ',' or json_str[i] == ':':
                tokens.append(json_str[i])
                i += 1
            elif json_str[i] == ' ':
                i += 1
            elif json_str[i] == '"':
                tokens.append('"')
                i += 1
                while i < len(json_str) and json_str[i] != '"':
                    if json_str[i] == '\\':
                        i += 1
                    i += 1
                tokens.append('"')
                i += 1
            elif json_str[i].isdigit() or json_str[i] == '-':
                num = ''
                while i < len(json_str) and (json_str[i].isdigit() or json_str[i] == '.'):
                    num += json_str[i]
                    i += 1
                tokens.append(num)
            elif json_str[i] == 't':
                tokens.append('true')
                i += 4
            elif json_str[i] == 'f':
                tokens.append('false')
                i += 5
            elif json_str[i] == 'n':
                tokens.append('null')
                i += 4
